def nan_data():
    X, y = data(25, 5, 3)
    for i in range(25):
        for j in range(5):
            if (i * 3 + j * 7) % 6 == 0:
                X[i, j] = np.nan
    X[2, 4] = 1.5; X[7, 4] = 1.5
    return X, y

