close("knn", KNNImputer(n_neighbors=3).fit_transform(X), knn)
close("knn_d", KNNImputer(n_neighbors=4, weights="distance").fit(X).transform(X[:8]), knn_d)
Xc = X[:, :4].copy()
for i in range(25):
    for j in range(4):
        if np.isnan(Xc[i, j]):
            Xc[i, j] = 0.0
yb = Xc @ np.array([1.0, -2.0, 0.5, 0.3]) + 0.1 * np.sin(np.arange(25).astype(float))
br = BayesianRidge(compute_score=True).fit(Xc, yb)
close("br_coef", br.coef_, br_coef); closes("br_int", br.intercept_, br_int, 1e-5)
closes("br_alpha", br.alpha_, br_alpha); closes("br_lambda", br.lambda_, br_lambda)
if br.n_iter_ != br_it:
    print("TEST FAILED br_it", br.n_iter_)
close("br_scores", br.scores_, br_scores)
m, sd = br.predict(Xc[:4], return_std=True); close("br_m", m, br_m); close("br_sd", sd, br_sd)
close("br2_coef", BayesianRidge().fit(Xc[:3], yb[:3]).coef_, br2_coef, 1e-5)
it = IterativeImputer(random_state=0)
close("it", it.fit_transform(X), it_e, 1e-5)
if it.n_iter_ != it_n:
    print("TEST FAILED it_n", it.n_iter_)
close("it_tr", it.transform(X[:5] + 0.5), it_tr, 1e-5)
it2 = IterativeImputer(random_state=0, n_nearest_features=2, imputation_order="random", max_iter=5)
close("it2", it2.fit_transform(X), it2_e, 1e-5)
it3 = IterativeImputer(initial_strategy="median", imputation_order="descending", min_value=-1.0, max_value=2.0, add_indicator=True)
close("it3", it3.fit_transform(X), it3_e, 1e-5)
